1	package org.springframework.samples.petclinic.service;
2	
3	import java.util.Map;
4	import java.util.concurrent.ConcurrentHashMap;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.stereotype.Component;
8	
9	/**
10	 * Tracks the owner created for each {@code Idempotency-Key} seen on owner creation.
11	 *
12	 * <p>A create that repeats with a key already recorded here can return the originally
13	 * created owner instead of creating a duplicate. Keeping this bookkeeping in a
14	 * dedicated component lets the REST controller stay a thin, stateless delegator.
15	 */
16	@Component
17	public class OwnerIdempotencyRegistry {
18	
19	    private final Map<String, Integer> ownerIdByKey = new ConcurrentHashMap<>();
20	
21	    private final ClinicService clinicService;
22	
23	    public OwnerIdempotencyRegistry(ClinicService clinicService) {
24	        this.clinicService = clinicService;
25	    }
26	
27	    /**
28	     * The owner already created for {@code key}, or {@code null} when the key is
29	     * absent/blank or has not yet produced an owner.
30	     */
31	    public Owner findCreatedOwner(String key) {
32	        if (key == null || key.isBlank()) {
33	            return null;
34	        }
35	        Integer ownerId = this.ownerIdByKey.get(key);
36	        return ownerId == null ? null : this.clinicService.findOwnerById(ownerId);
37	    }
38	
39	    /** Record that {@code key} produced {@code owner}; a no-op when the key is absent/blank. */
40	    public void record(String key, Owner owner) {
41	        if (key != null && !key.isBlank()) {
42	            this.ownerIdByKey.put(key, owner.getId());
43	        }
44	    }
45	}
